"""Certified digit-statistic auditor.

Computes the first- and second-order digit statistics of a designed number and compares
them against the bounds proved for the constructions:

    nonzero digits of the sparse graft below M     <=  n + log2(M) + 1
    zero digits of the dense graft below M         <=  n
    lag-r disagreements of the dense graft below M <=  n + r + 3 + 2 log2(M)
    lag-1 agreements of the alternating graft      <=  n + 4 + 2 log2(M)
    lag-2 disagreements of the alternating graft   <=  n + 5 + 2 log2(M)

Each bound is logarithmic in M, hence the corresponding density is 0 or 1 in the limit.
"""

from __future__ import annotations

from typing import Callable, Dict, Iterable, List, Tuple

DigitRule = Callable[[int], int]


def int_log2(n: int) -> int:
    """floor(log2 n) for n >= 1, and 0 for n = 0."""
    return n.bit_length() - 1 if n > 0 else 0


def nonzero_count(rule: DigitRule, bound: int) -> int:
    """#{m < bound : d_m != 0}.  O(bound)."""
    return sum(1 for m in range(bound) if rule(m) != 0)


def digit_histogram(rule: DigitRule, bound: int) -> Dict[int, int]:
    """Counts of each digit 0..9 among the first `bound` digits.  O(bound)."""
    hist = {c: 0 for c in range(10)}
    for m in range(bound):
        hist[rule(m)] += 1
    return hist


def agree_count(rule: DigitRule, lag: int, bound: int) -> int:
    """A_r(M) = #{m < M : d_m = d_{m+r}}.  O(bound)."""
    return sum(1 for m in range(bound) if rule(m) == rule(m + lag))


def autocorrelation_profile(rule: DigitRule, lags: Iterable[int],
                            bound: int) -> Dict[int, float]:
    """The map r -> A_r(M)/M.  O(bound * #lags)."""
    return {r: agree_count(rule, r, bound) / bound for r in lags}


def audit(rule: DigitRule, prefix_len: int, scales: Iterable[int],
          lags: Iterable[int]) -> List[Tuple[int, int, float, Dict[int, float]]]:
    """For each scale M, return (M, nonzero count, nonzero density, autocorrelation profile)
       together with the certified logarithmic budget n + O(log2 M)."""
    rows: List[Tuple[int, int, float, Dict[int, float]]] = []
    for M in scales:
        nz = nonzero_count(rule, M)
        rows.append((M, nz, nz / M, autocorrelation_profile(rule, lags, M)))
    return rows


def certified_budget(prefix_len: int, M: int, lag: int = 0) -> int:
    """The exceptional-set bound n + (log2 M + 1) + (log2 M + r + 1) proved for the grafts."""
    return prefix_len + (int_log2(M) + 1) + (int_log2(M) + lag + 1)


if __name__ == "__main__":
    sparse: DigitRule = lambda m: 1 if ((m + 1) & m) == 0 else 0
    dense: DigitRule = lambda m: 2 if ((m + 1) & m) == 0 else 1
    for M in (100, 1000, 10000):
        nz = nonzero_count(sparse, M)
        dis = M - agree_count(dense, 3, M)
        print(f"M={M:6d}  sparse nonzero={nz:3d} (bound {int_log2(M)+1:3d})"
              f"   dense lag-3 disagreements={dis:3d} (budget {certified_budget(0, M, 3):3d})")
